do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solutions t where id='d142ab68-608d-5999-a1f9-9a7ad5adfd06'; if prior is not null then if not prior @> '{"id":"d142ab68-608d-5999-a1f9-9a7ad5adfd06","leaf_id":"30f04d40-1c56-5944-a120-a4681dab57b8","source_id":"b3976022-c6ec-5875-82f2-28dd76717258","origin":"OFFICIAL","body":"V=∫₁ᵗ(ln y)²dy, W=(√3/4)∫₀ˡⁿᵗ(t−eˣ)²dx이다. 부분적분 후 최고차항을 비교하면 (ln t/t)W/V→√3/4.\n호의 길이는 (8/27)[((9t+13)/4)^(3/2)−1], 원점까지 거리는 √(t²+(t+1)³)이다. 두 식을 t^(3/2)로 나눈 비의 극한은 1이다.\n연속함수로 확장해 미분하면 양의 구간에서 도함수 부호는 x²+x−43의 부호다. 최솟점 양쪽의 정수 6,7을 비교하면 1/13²<4/15²이므로 n=6이다.","logical_id":"d142ab68-608d-5999-a1f9-9a7ad5adfd06","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solutions (id,leaf_id,source_id,origin,body,logical_id,version,state) values ('d142ab68-608d-5999-a1f9-9a7ad5adfd06','30f04d40-1c56-5944-a120-a4681dab57b8','b3976022-c6ec-5875-82f2-28dd76717258','OFFICIAL','V=∫₁ᵗ(ln y)²dy, W=(√3/4)∫₀ˡⁿᵗ(t−eˣ)²dx이다. 부분적분 후 최고차항을 비교하면 (ln t/t)W/V→√3/4.
호의 길이는 (8/27)[((9t+13)/4)^(3/2)−1], 원점까지 거리는 √(t²+(t+1)³)이다. 두 식을 t^(3/2)로 나눈 비의 극한은 1이다.
연속함수로 확장해 미분하면 양의 구간에서 도함수 부호는 x²+x−43의 부호다. 최솟점 양쪽의 정수 6,7을 비교하면 1/13²<4/15²이므로 n=6이다.','d142ab68-608d-5999-a1f9-9a7ad5adfd06',1,'DRAFT'); end if; end $row$;
