do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_problems t where id='10dde9e7-5e04-5d50-985d-29bd974256fe'; if prior is not null then if not prior @> '{"id":"10dde9e7-5e04-5d50-985d-29bd974256fe","problem_set_id":"d4af9045-ccc5-5df3-ae42-d372a15c5a81","display_order":2,"statement":"[문제 2] 다음 제시문을 읽고 물음에 답하시오. (50점)\n 이하의 모든 양의 실수  ,  ,  와    을 만족시키는 실수  에 대하여 부등식\n\n        \n      \n≥ \n을 만족시키는 양의 실수 의 최댓값을 다음과 같이 구하고자 한다.\n위 부등식을 아래와 같이 쓰자.\n\n      \n  \n\n  \n  \n\n  \n\n\n\n        \n  \n (단,    ≤  )이라 하면,\n\n  \n  \n\n  \n\n\n\nㄱ \n′  \n\n\n\n\n\n\n\n\n  \n  \n  \n\n\n\n \n≥ \n \n \n\n\n\n\n\n≤ \n이므로  ≥  이 성립한다.\n이번에는    가 되도록         \n  \n (단,    ≤  )이라 하면,\n\n  \n  \n  \n\n\n\n′ ≤  이므로  ≥  이 성립한다.\n마지막으로     \n\n    가 되는  를 생각하면……\n(이하 생략)\n1. 제시문의 ㄱ 에 알맞은 수식을 쓰고 ′ ≤  인 이유를 설명하시오.\n2. 제시문에서 생략된 마지막 과정을 완성하여 의 최댓값을 구하시오.\n3. 다음 부등식을 만족시키는 양의 실수 의 최댓값을 제시문과 동일한 방법으로 구하시오.\n(단, 실수 , , ,  는 제시문과 동일한 조건을 만족한다.)\n\n        \n      \n≥ ","logical_id":"10dde9e7-5e04-5d50-985d-29bd974256fe","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_problems (id,problem_set_id,display_order,statement,logical_id,version,state) values ('10dde9e7-5e04-5d50-985d-29bd974256fe','d4af9045-ccc5-5df3-ae42-d372a15c5a81',2,'[문제 2] 다음 제시문을 읽고 물음에 답하시오. (50점)
