do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solutions t where id='6736ae3c-83d6-5100-bee2-501791a9d12b'; if prior is not null then if not prior @> '{"id":"6736ae3c-83d6-5100-bee2-501791a9d12b","leaf_id":"214ba2cf-bbbd-5e65-8612-f08b66a48b04","source_id":"59094c15-f4dc-5261-9de3-1edb65765ae7","origin":"OFFICIAL","body":"정사영 높이는 cosθ/√2이고 평행 성분은 1/√2이므로 A′B′=√((1+cos²θ)/2)이다.\nPQ의 두 성분을 나누면 P′Q′=√(sin²t cos²θ+cos²t)이다.\n정삼각형 세 변의 정사영 길이 제곱합은 (3/2)(1+cos²θ)이다. cosθ=3/π를 대입하면 (27+3π²)/(2π²)이다.","logical_id":"6736ae3c-83d6-5100-bee2-501791a9d12b","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solutions (id,leaf_id,source_id,origin,body,logical_id,version,state) values ('6736ae3c-83d6-5100-bee2-501791a9d12b','214ba2cf-bbbd-5e65-8612-f08b66a48b04','59094c15-f4dc-5261-9de3-1edb65765ae7','OFFICIAL','정사영 높이는 cosθ/√2이고 평행 성분은 1/√2이므로 A′B′=√((1+cos²θ)/2)이다.
PQ의 두 성분을 나누면 P′Q′=√(sin²t cos²θ+cos²t)이다.
정삼각형 세 변의 정사영 길이 제곱합은 (3/2)(1+cos²θ)이다. cosθ=3/π를 대입하면 (27+3π²)/(2π²)이다.','6736ae3c-83d6-5100-bee2-501791a9d12b',1,'DRAFT'); end if; end $row$;
