do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_problems t where id='1fd47ea2-99c0-535b-93ff-049d3a80ff3e'; if prior is not null then if not prior @> '{"id":"1fd47ea2-99c0-535b-93ff-049d3a80ff3e","problem_set_id":"2fe91c38-8168-537e-8dda-913a73180274","display_order":1,"statement":"[문제 1] 다음 제시문을 읽고 물음에 답하시오. (50점)\n<가> 오른쪽 그림과 같이 반지름의 길이가 인 원 위의 두 점\nP , Q 를 잇는 한 호 PQ 의 길이를  라고 할 때, 현 PQ 의 길이를\n, 현 PQ 와 길이가  인 호 PQ 로 둘러싸인 도형의 넓이를 \n라고 하자.\n<나> 반지름의 길이가 인 원 위에 서로 다른  개의 점\nP , P,\n\nP P \n⋯\n, P 이 순서대로 놓여 있고,\n\n\nP P  ⋯ \nP  P  \n\nP  P 을 만족시킨다.\n예를 들어, 오른쪽 그림은    인 경우이다.\n1. 제시문 <가>에서 주어진 식  ,  에 대하여 극한값 lim\n\n 를 구하시오.\n → \n \n2. 제시문 <나>에서 주어진  개의 점 P , P,\n⋯\n, P 에 대하여 극한값\n\n\n\nP P \nP P  ⋯ \nP P \n\nlim\n→∞\n\n을 구하시오.\n3. 제시문 <나>에서 주어진  개의 점 P , P,\n⋯\n넓이를   , 호 P P 와 현 P P 로 둘러싸인 도형의 넓이를   ,\n도형의 넓이를    이라 하자. 극한값\n, P 에 대하여 호 P P 과 현 P P 로 둘러싸인 도형의\n⋯\n, 호 P P  과 현 P P  로 둘러싸인\nlim\n→∞\n \n   \n\n  ⋯    \n\n\n을 구하시오. (단,       ⋯     이 되도록 호를 선택한다.)","logical_id":"1fd47ea2-99c0-535b-93ff-049d3a80ff3e","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_problems (id,problem_set_id,display_order,statement,logical_id,version,state) values ('1fd47ea2-99c0-535b-93ff-049d3a80ff3e','2fe91c38-8168-537e-8dda-913a73180274',1,'[문제 1] 다음 제시문을 읽고 물음에 답하시오. (50점)
