do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solutions t where id='f3e6bae0-0e5e-5aca-b3c0-ded40af05793'; if prior is not null then if not prior @> '{"id":"f3e6bae0-0e5e-5aca-b3c0-ded40af05793","leaf_id":"5191b890-24e7-5987-8605-fe5ce34dab16","source_id":"081235e3-1732-5920-89eb-78c139d25771","origin":"OFFICIAL","body":"코사인법칙과 수선으로 AR=√3,RH=√3/2,PR=√3/4,AP=3√3/4를 얻는다. OP²=7/16,BP²=19/16이므로 합은 13/8이다.\nR=(cos t,sin t),H=(cos t,0)로 놓고 직선 AR과 H를 지나 AR에 수직인 직선을 연립한다. P=((cos²t+2cos t−1)/2,sin t(1+cos t)/2)이다. OP²=(cos³t+cos²t−cos t+1)/2를 미분하면 cos t=1/3에서 최솟값 OP=√33/9이다.\nP의 좌표에서 cos t=−1+√(2+2x)이므로 y²=√2(1+x)^(3/2)−(1+x)²이다. 이를 −1부터 1까지 적분하면 부피는 8/15이다.","logical_id":"f3e6bae0-0e5e-5aca-b3c0-ded40af05793","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solutions (id,leaf_id,source_id,origin,body,logical_id,version,state) values ('f3e6bae0-0e5e-5aca-b3c0-ded40af05793','5191b890-24e7-5987-8605-fe5ce34dab16','081235e3-1732-5920-89eb-78c139d25771','OFFICIAL','코사인법칙과 수선으로 AR=√3,RH=√3/2,PR=√3/4,AP=3√3/4를 얻는다. OP²=7/16,BP²=19/16이므로 합은 13/8이다.
R=(cos t,sin t),H=(cos t,0)로 놓고 직선 AR과 H를 지나 AR에 수직인 직선을 연립한다. P=((cos²t+2cos t−1)/2,sin t(1+cos t)/2)이다. OP²=(cos³t+cos²t−cos t+1)/2를 미분하면 cos t=1/3에서 최솟값 OP=√33/9이다.
P의 좌표에서 cos t=−1+√(2+2x)이므로 y²=√2(1+x)^(3/2)−(1+x)²이다. 이를 −1부터 1까지 적분하면 부피는 8/15이다.','f3e6bae0-0e5e-5aca-b3c0-ded40af05793',1,'DRAFT'); end if; end $row$;
