do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_problems t where id='fae49687-328d-5612-8b55-226b8932bea0'; if prior is not null then if not prior @> '{"id":"fae49687-328d-5612-8b55-226b8932bea0","problem_set_id":"17235173-f0ce-56cc-8ab2-d5bd257683aa","display_order":2,"statement":"[문제 2] 다음 물음에 답하시오. (50점)\n\n1. 수열  은 모든 자연수  에 대하여 \n  \n  \n\nsin\n cos   를 만족시킨다.\n∞\n\n\n \n\n  \n 일 때, tan  의 값을 구하시오. 단,     \n \n\n2. 평균이  , 표준편차가  인 정규분포를 따르는 모집단에서 크기가  인 표본을 임의추출할 때,\n표본평균을\n\n 라 하자. 이 모집단의 확률변수를 라 할 때, 두 확률변수 ,\n\n 가 다음\n세 조건을 만족시킨다. 이때,      의 값을 구하시오. (단, 가 표준정규분포를 따르는\n확률변수일 때, P ≤ ≤    , P ≤ ≤    , P ≤ ≤   로 계산한다.)\n\n(가) P≥   P\n≥   \n\n(나) P≥   P\n≥   \n(다) 표본평균의 값이 \n 일 때,  에 대한 신뢰도  %의 신뢰구간이 \n   ≤  ≤\n\n   이다.\n3. 평평한 면과 둥근 면이 나올 확률이 각각 ,    인 윷짝 한 개를  번 던졌을 때, 평평한 면이\n나온 횟수가 짝수일 확률을  에 대한 식으로 나타내시오. (단,  은 짝수이다.)","logical_id":"fae49687-328d-5612-8b55-226b8932bea0","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_problems (id,problem_set_id,display_order,statement,logical_id,version,state) values ('fae49687-328d-5612-8b55-226b8932bea0','17235173-f0ce-56cc-8ab2-d5bd257683aa',2,'[문제 2] 다음 물음에 답하시오. (50점)
