do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_problems t where id='2dbf2fe9-7c01-5aa8-8388-1fa59f1ec20a'; if prior is not null then if not prior @> '{"id":"2dbf2fe9-7c01-5aa8-8388-1fa59f1ec20a","problem_set_id":"fc56ae4e-e365-5bcb-8a97-c40b5e71ec7e","display_order":1,"statement":"[문제 1] 다음 제시문을 읽고 물음에 답하시오. (50점)\n<가> 함수  는 다음 조건을 만족시킨다.\n   \n\n   \n  \n<나> 함수  는 다음 조건을 만족시킨다.\n(1)   \n(2)   \n\n\n′   \n\n \n\n′   sin\n1. 제시문 <가>에서 주어진 곡선    의 오목과 볼록을 조사하고 변곡점의 좌표를 구하시오.\n2. 제시문 <가>에서 주어진 곡선    위의 점   에서의 접선을  , 점   에서의 접선을\n 라고 하자. 곡선    와 두 직선  ,  로 둘러싸인 도형의 넓이를 구하시오.\n3. 제시문 <나>에서 주어진 함수  에 대하여,  \n\n   \n 이 성립함을 보이시오.","logical_id":"2dbf2fe9-7c01-5aa8-8388-1fa59f1ec20a","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_problems (id,problem_set_id,display_order,statement,logical_id,version,state) values ('2dbf2fe9-7c01-5aa8-8388-1fa59f1ec20a','fc56ae4e-e365-5bcb-8a97-c40b5e71ec7e',1,'[문제 1] 다음 제시문을 읽고 물음에 답하시오. (50점)
