do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solutions t where id='01695947-38f6-50c2-97f6-8c153fab6bde'; if prior is not null then if not prior @> '{"id":"01695947-38f6-50c2-97f6-8c153fab6bde","leaf_id":"1db9c975-1c3f-5b3a-bd25-c98fd9376e44","source_id":"90996c6e-f92a-590a-afe3-d8607cb4a048","origin":"OFFICIAL","body":"AP=t,0≤t≤1/2라 놓으면 PB=√(t²+1),PH=√(t²−2t+2)이다. 코사인법칙과 넓이 √7/4로부터 t=(2−√2)/4이다. 정사영 삼각형의 넓이는 PD/2=(2+√2)/8이다.\nA_(n+1)−A_n은 세 변 중 하나 이상이 n+1인 순서 있는 삼각형 수이다. 하나,둘,셋인 경우를 나누면 3n(n−1)/2+3n+1=3n(n+1)/2+1이다.\n조합의 대칭성과 이항정리로 Σ[k=0,n/3]C(n,k)<((1+x)/x^(2/3))^n (x>1)이다. 이 우변의 밑은 x=2에서 최소이고 1.9보다 작으므로 요구 부등식이 성립한다.","logical_id":"01695947-38f6-50c2-97f6-8c153fab6bde","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solutions (id,leaf_id,source_id,origin,body,logical_id,version,state) values ('01695947-38f6-50c2-97f6-8c153fab6bde','1db9c975-1c3f-5b3a-bd25-c98fd9376e44','90996c6e-f92a-590a-afe3-d8607cb4a048','OFFICIAL','AP=t,0≤t≤1/2라 놓으면 PB=√(t²+1),PH=√(t²−2t+2)이다. 코사인법칙과 넓이 √7/4로부터 t=(2−√2)/4이다. 정사영 삼각형의 넓이는 PD/2=(2+√2)/8이다.
A_(n+1)−A_n은 세 변 중 하나 이상이 n+1인 순서 있는 삼각형 수이다. 하나,둘,셋인 경우를 나누면 3n(n−1)/2+3n+1=3n(n+1)/2+1이다.
조합의 대칭성과 이항정리로 Σ[k=0,n/3]C(n,k)<((1+x)/x^(2/3))^n (x>1)이다. 이 우변의 밑은 x=2에서 최소이고 1.9보다 작으므로 요구 부등식이 성립한다.','01695947-38f6-50c2-97f6-8c153fab6bde',1,'DRAFT'); end if; end $row$;
