do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solutions t where id='18e81d7c-4c2e-5666-b8e0-38ce42421eb6'; if prior is not null then if not prior @> '{"id":"18e81d7c-4c2e-5666-b8e0-38ce42421eb6","leaf_id":"2ca58a65-d7e0-5c81-b521-f01dc91bd99b","source_id":"5ead9cde-7ac1-525a-9d87-ff94cb36f844","origin":"OFFICIAL","body":"파스칼 항등식을 세 번 적용하여 C(3n+3,3k)=C(3n,3k−3)+3C(3n,3k−2)+3C(3n,3k−1)+C(3n,3k)를 얻는다.\n위 식을 합하고 조합의 대칭성을 사용하면 a_(n+1)+a_n=3Σ[k=0,3n]C(3n,k)=3·2^(3n)이다.\n교대합으로 a_1+a_100=(8/3)(8^99+1)이고 a_1=2이므로 a_100=(8^100+2)/3이다. 대칭인 나머지 두 조합합이 같으므로 요구 합은 (8^100−1)/3이다.","logical_id":"18e81d7c-4c2e-5666-b8e0-38ce42421eb6","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solutions (id,leaf_id,source_id,origin,body,logical_id,version,state) values ('18e81d7c-4c2e-5666-b8e0-38ce42421eb6','2ca58a65-d7e0-5c81-b521-f01dc91bd99b','5ead9cde-7ac1-525a-9d87-ff94cb36f844','OFFICIAL','파스칼 항등식을 세 번 적용하여 C(3n+3,3k)=C(3n,3k−3)+3C(3n,3k−2)+3C(3n,3k−1)+C(3n,3k)를 얻는다.
위 식을 합하고 조합의 대칭성을 사용하면 a_(n+1)+a_n=3Σ[k=0,3n]C(3n,k)=3·2^(3n)이다.
교대합으로 a_1+a_100=(8/3)(8^99+1)이고 a_1=2이므로 a_100=(8^100+2)/3이다. 대칭인 나머지 두 조합합이 같으므로 요구 합은 (8^100−1)/3이다.','18e81d7c-4c2e-5666-b8e0-38ce42421eb6',1,'DRAFT'); end if; end $row$;
