do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solutions t where id='a068bb39-dbc8-5509-bbc8-e4dd607a2722'; if prior is not null then if not prior @> '{"id":"a068bb39-dbc8-5509-bbc8-e4dd607a2722","leaf_id":"cc7a94e7-bf90-50d0-a230-5b8d3ffa9d88","source_id":"ee90dd94-083a-521c-ae7f-7259d9b231c4","origin":"OFFICIAL","body":"f(x)=ln(x+α)/(x+α)의 도함수는 (1−ln(x+α))/(x+α)²이다. 최댓값은 x=e−α에서 1/e이고 0<t<1/e에 대해서만 f(x)=t의 해가 두 개다. 따라서 0<e−α<1/e, 즉 e−1/e<α<e이다.\nf′(−1)=a,f′(1)=−b로 두면 두 접선의 교점은 ((b−a)/(a+b),2ab/(a+b))이고 S=2ab/(a+b)이다. 각의 덧셈정리로 cotθ=ab/(a+b)−1/(a+b)=S/2−1/23이다.\n원 (x−t)²+(y−1)²=1과 두 직선 y=±√3x+1을 연립한다. 교점 사이 현 PQ의 길이는 항상 1이어서 활꼴 넓이는 일정하다. AP·AQ=1−t²이므로 가변 삼각형 넓이는 √3(1−t²)/4이다. 이를 미분하여 f′(√2/2)=−√6/4를 얻는다.","logical_id":"a068bb39-dbc8-5509-bbc8-e4dd607a2722","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solutions (id,leaf_id,source_id,origin,body,logical_id,version,state) values ('a068bb39-dbc8-5509-bbc8-e4dd607a2722','cc7a94e7-bf90-50d0-a230-5b8d3ffa9d88','ee90dd94-083a-521c-ae7f-7259d9b231c4','OFFICIAL','f(x)=ln(x+α)/(x+α)의 도함수는 (1−ln(x+α))/(x+α)²이다. 최댓값은 x=e−α에서 1/e이고 0<t<1/e에 대해서만 f(x)=t의 해가 두 개다. 따라서 0<e−α<1/e, 즉 e−1/e<α<e이다.
f′(−1)=a,f′(1)=−b로 두면 두 접선의 교점은 ((b−a)/(a+b),2ab/(a+b))이고 S=2ab/(a+b)이다. 각의 덧셈정리로 cotθ=ab/(a+b)−1/(a+b)=S/2−1/23이다.
원 (x−t)²+(y−1)²=1과 두 직선 y=±√3x+1을 연립한다. 교점 사이 현 PQ의 길이는 항상 1이어서 활꼴 넓이는 일정하다. AP·AQ=1−t²이므로 가변 삼각형 넓이는 √3(1−t²)/4이다. 이를 미분하여 f′(√2/2)=−√6/4를 얻는다.','a068bb39-dbc8-5509-bbc8-e4dd607a2722',1,'DRAFT'); end if; end $row$;
