do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_scoring_criteria t where id='7dbf088d-b8c4-5da6-9875-a1d9372b4d66'; if prior is not null then if not prior @> '{"id":"7dbf088d-b8c4-5da6-9875-a1d9372b4d66","leaf_id":"b53af2c1-db5b-5820-b1a9-41479c118695","source_id":"d3daed1b-f2c3-5359-bf90-5241eacd699c","criterion_key":"q2-6","description":"관계식으로 코사인 극한 계산","official_points":null,"rubric_dimensions":["logical_development","computation_accuracy","final_conclusion"]}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_scoring_criteria (id,leaf_id,source_id,criterion_key,description,official_points,rubric_dimensions) values ('7dbf088d-b8c4-5da6-9875-a1d9372b4d66','b53af2c1-db5b-5820-b1a9-41479c118695','d3daed1b-f2c3-5359-bf90-5241eacd699c','q2-6','관계식으로 코사인 극한 계산',NULL,ARRAY['logical_development','computation_accuracy','final_conclusion']::text[]); end if; end $row$;
do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solutions t where id='88fca2c7-3b94-5619-96a2-04fe929945f8'; if prior is not null then if not prior @> '{"id":"88fca2c7-3b94-5619-96a2-04fe929945f8","leaf_id":"b53af2c1-db5b-5820-b1a9-41479c118695","source_id":"97711c2f-04e7-539c-84cb-bacfbc6d1649","origin":"OFFICIAL","body":"P=(a,b),Q=(b,a),a²/3+b²/2=1에서 내적은 2b(a+1)이다. f(a)=2√2(a+1)√(1−a²/3)를 [−√3,√3]에서 미분하면 임계점은 −3/2,1이다. f와 −f의 최댓값을 비교하여 8√3/3을 얻는다.\n겹친 도형의 넓이는 삼각형 OMN 넓이의 8배다. 각 관계와 높이 1/2를 이용하면 S(θ)=(1−tan(θ/2))/(1+tan(θ/2))+tan(θ/2)이다. 미분 후 θ=π/3 대입으로 S′(π/3)=2√3−10/3이다.\n교점이 4n+1개일 때 (2nπ,(2n+1)π)에서 접한다. cos x_n=1−a_n x_n²와 sin x_n=2a_n x_n을 제곱하여 더하면 x_n²=2/a_n−4이다. cos x_n=1−2x_n²/(x_n²+4)이고 x_n→∞이므로 극한은 −1이다.","logical_id":"88fca2c7-3b94-5619-96a2-04fe929945f8","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solutions (id,leaf_id,source_id,origin,body,logical_id,version,state) values ('88fca2c7-3b94-5619-96a2-04fe929945f8','b53af2c1-db5b-5820-b1a9-41479c118695','97711c2f-04e7-539c-84cb-bacfbc6d1649','OFFICIAL','P=(a,b),Q=(b,a),a²/3+b²/2=1에서 내적은 2b(a+1)이다. f(a)=2√2(a+1)√(1−a²/3)를 [−√3,√3]에서 미분하면 임계점은 −3/2,1이다. f와 −f의 최댓값을 비교하여 8√3/3을 얻는다.
겹친 도형의 넓이는 삼각형 OMN 넓이의 8배다. 각 관계와 높이 1/2를 이용하면 S(θ)=(1−tan(θ/2))/(1+tan(θ/2))+tan(θ/2)이다. 미분 후 θ=π/3 대입으로 S′(π/3)=2√3−10/3이다.
교점이 4n+1개일 때 (2nπ,(2n+1)π)에서 접한다. cos x_n=1−a_n x_n²와 sin x_n=2a_n x_n을 제곱하여 더하면 x_n²=2/a_n−4이다. cos x_n=1−2x_n²/(x_n²+4)이고 x_n→∞이므로 극한은 −1이다.','88fca2c7-3b94-5619-96a2-04fe929945f8',1,'DRAFT'); end if; end $row$;
