do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solution_steps t where id='c2d53c8e-9a3a-567b-ab6d-80d9fc55e81c'; if prior is not null then if not prior @> '{"id":"c2d53c8e-9a3a-567b-ab6d-80d9fc55e81c","solution_id":"88fca2c7-3b94-5619-96a2-04fe929945f8","position":2,"body":"겹친 도형의 넓이는 삼각형 OMN 넓이의 8배다. 각 관계와 높이 1/2를 이용하면 S(θ)=(1−tan(θ/2))/(1+tan(θ/2))+tan(θ/2)이다. 미분 후 θ=π/3 대입으로 S′(π/3)=2√3−10/3이다.","criterion_id":null}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solution_steps (id,solution_id,position,body,criterion_id) values ('c2d53c8e-9a3a-567b-ab6d-80d9fc55e81c','88fca2c7-3b94-5619-96a2-04fe929945f8',2,'겹친 도형의 넓이는 삼각형 OMN 넓이의 8배다. 각 관계와 높이 1/2를 이용하면 S(θ)=(1−tan(θ/2))/(1+tan(θ/2))+tan(θ/2)이다. 미분 후 θ=π/3 대입으로 S′(π/3)=2√3−10/3이다.',NULL); end if; end $row$;
