do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_problems t where id='d9fb0528-9d9c-5752-8807-f896d5d4dd8a'; if prior is not null then if not prior @> '{"id":"d9fb0528-9d9c-5752-8807-f896d5d4dd8a","problem_set_id":"d6e7de78-73e1-5ad4-9c58-78e2b62317e8","display_order":1,"statement":"[문제 1] 다음 물음에 답하시오. (50점)\n1.  ≤  \n\n구하시오.\n\n  \n    ≤ 을 만족시키는  이하의 두 자연수  ,  의 모든 순서쌍   의 개수를\n2. 그림과 같이 정사각형이 가로로 개, 세로로 개씩 놓여 있는\n정사각형 모양으로 연결된 도로망이 있다. 지점 A에서 출발하여\n지점 B까지 최단 거리로 갈 때, 지점 A와 지점 B를 제외하고\n이동 방향이 바뀌는 지점의 개수가  인 경우의 수를 ,\n이동 방향이 바뀌는 지점의 개수가  인 경우의 수를  \n이라 하자. 과 \n ×  의 값을 구하시오.\n(오른쪽 그림에서 굵은 선은 이동 방향이 바뀌는 지점의\n개수가  인 경로 중 하나이다.)\n3. 실수 전체의 집합에서 정의된 두 함수  와  는 다음 조건을 만족시킨다.\n<가>  는 삼차함수이고,      , \n′   , \n′\n′   이다.\n<나> 자연수  에 대하여 \n   \n\n  이고,\n ≤    일 때   ,\n ≤    (  , , )일 때   \n\n  \n \n  \n\n      이다.\n<다> 는 닫힌구간    에서 연속이고, 열린구간    에서 미분가능하다.\n이때  \n 의 값을 구하시오.","logical_id":"d9fb0528-9d9c-5752-8807-f896d5d4dd8a","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_problems (id,problem_set_id,display_order,statement,logical_id,version,state) values ('d9fb0528-9d9c-5752-8807-f896d5d4dd8a','d6e7de78-73e1-5ad4-9c58-78e2b62317e8',1,'[문제 1] 다음 물음에 답하시오. (50점)
