do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_scoring_criteria t where id='35cd3cfd-e1e8-5af9-a9ab-c4ef14aba810'; if prior is not null then if not prior @> '{"id":"35cd3cfd-e1e8-5af9-a9ab-c4ef14aba810","leaf_id":"98041eaa-b40c-53d1-b295-67e946bb59eb","source_id":"8b4fff26-0f2d-569a-9c01-9819c52ae3fd","criterion_key":"q2-7","description":"APC와 PEG 넓이로 cosθ 계산","official_points":null,"rubric_dimensions":["logical_development","computation_accuracy","final_conclusion"]}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_scoring_criteria (id,leaf_id,source_id,criterion_key,description,official_points,rubric_dimensions) values ('35cd3cfd-e1e8-5af9-a9ab-c4ef14aba810','98041eaa-b40c-53d1-b295-67e946bb59eb','8b4fff26-0f2d-569a-9c01-9819c52ae3fd','q2-7','APC와 PEG 넓이로 cosθ 계산',NULL,ARRAY['logical_development','computation_accuracy','final_conclusion']::text[]); end if; end $row$;
do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solutions t where id='5e27bc1a-dc5a-588e-99d2-f85b4b6e45e8'; if prior is not null then if not prior @> '{"id":"5e27bc1a-dc5a-588e-99d2-f85b4b6e45e8","leaf_id":"98041eaa-b40c-53d1-b295-67e946bb59eb","source_id":"aa0148c5-0fe6-5f24-b9ff-c7ba97e4114b","origin":"OFFICIAL","body":"두 곡선 교점 θ에서 cosθ=n/(n+1)이다. 각 접선의 x절편으로 S_n=sin²θ(1/cosθ−cosθ)/2=(2n+1)²/(2n(n+1)³)을 얻고 n²S_n의 극한은 2이다.\n포물선 접선 y_1y=2p(x+x_1)과 준선의 교점 및 대칭점으로 P′=((x_1−p)²/(4x_1),2p(x_1−p)/y_1)이다. 초점 벡터 내적에서 cosθ=(x_1−p)/(x_1+p)=1/5이므로 x_1=3p/2이다.\n평면의 교선으로 PQ와 CD의 평행을 증명하고 닮음으로 PQ=3을 얻는다. PG=√10,AP=CP=√26,AC=4√2이므로 삼각형 APC 넓이는 12이다. 정사영 삼각형 PEG 넓이는 4이므로 cosθ=1/3이다.","logical_id":"5e27bc1a-dc5a-588e-99d2-f85b4b6e45e8","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solutions (id,leaf_id,source_id,origin,body,logical_id,version,state) values ('5e27bc1a-dc5a-588e-99d2-f85b4b6e45e8','98041eaa-b40c-53d1-b295-67e946bb59eb','aa0148c5-0fe6-5f24-b9ff-c7ba97e4114b','OFFICIAL','두 곡선 교점 θ에서 cosθ=n/(n+1)이다. 각 접선의 x절편으로 S_n=sin²θ(1/cosθ−cosθ)/2=(2n+1)²/(2n(n+1)³)을 얻고 n²S_n의 극한은 2이다.
포물선 접선 y_1y=2p(x+x_1)과 준선의 교점 및 대칭점으로 P′=((x_1−p)²/(4x_1),2p(x_1−p)/y_1)이다. 초점 벡터 내적에서 cosθ=(x_1−p)/(x_1+p)=1/5이므로 x_1=3p/2이다.
평면의 교선으로 PQ와 CD의 평행을 증명하고 닮음으로 PQ=3을 얻는다. PG=√10,AP=CP=√26,AC=4√2이므로 삼각형 APC 넓이는 12이다. 정사영 삼각형 PEG 넓이는 4이므로 cosθ=1/3이다.','5e27bc1a-dc5a-588e-99d2-f85b4b6e45e8',1,'DRAFT'); end if; end $row$;
