do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_problems t where id='f8ca9555-019a-5be2-8ee2-0ddd08ab4e7e'; if prior is not null then if not prior @> '{"id":"f8ca9555-019a-5be2-8ee2-0ddd08ab4e7e","problem_set_id":"95f3b3f7-f7e0-5cc9-9d98-4a42bc07724c","display_order":1,"statement":"[문제 1] 다음 물음에 답하시오. (50점)\n1. 곡선   \n   \n\n   을  축의 방향으로  만큼,  축의 방향으로 만큼 평행이동한 곡선을    라 하자.\n모든 실수  에 대하여      가 성립할 때,  과  의 값을 구하고, 이 두 곡선으로 둘러싸인 도형의\n넓이를 구하시오.\n2. 세 변 AB, BC, CA의 길이가 각각 , , 인 삼각형 ABC 가 있다.\n삼각형 PQR 은 다음 조건을 만족시킨다.\n<가> 꼭짓점 P, Q, R은 각각 선분 AB, BC, CA 위에 있다.\n<나> 두 선분 PQ 와 QR 은 서로 수직이고\n\n\nPQ \nQR 이다.\n\nBP   ( ≤  ≤  )라 할 때, 삼각형 PQR 의 넓이를  에 대한 식으로\n나타내고, 삼각형 PQR 의 넓이가 최소가 되게 하는  의 값을 구하시오.\n3. 정삼각형 ABC과     \n 인 상수  에 대하여 점 A\n′\n\n, B\n′\n, C\n′은 각각 변 AB, BC, CA 위에 있고,\n\n\nAA\n′\n \nAB ,\n\n\nBB\n′\n \nBC ,\n\n\nCC\n′\n \nCA 을 만족시킨다. 아래 그림과 같이 선분 AB\n′과 CA\n′이\n만나는 점을 A, 선분 BC\n′과 AB\n′이 만나는 점을 B, 선분 CA\n′과 BC\n′이 만나는 점을 C라 하면\n삼각형 ABC는 정삼각형이다.\n정삼각형 ABC에도 같은 방법을 적용하여, 각각 변 AB, BC, C A 위에 있고\n\n\nAA\n′\n \nAB ,\n\n\nBB\n′\n \nBC ,\n\n\nCC\n′\n \nC A 를 만족시키는 점을 각각 A\n′\n, B\n′\n, C\n′이라 하면\n선분 AB\n′과 C A\n′이 만나는 점 A, 선분 BC\n′과 AB\n′이 만나는 점 B, 선분 C A\n′과 BC\n′이 만나는\n점 C을 세 꼭짓점으로 하는 정삼각형 ABC을 얻는다. 이와 같은 과정을 반복하여\n정삼각형 ABC ( ≥ )을 얻을 수 있다. 자연수  에 대하여 정삼각형 ABC의 넓이를 이라 하자.\n\n∞\n  을 만족시키는 을 에 대한 식으로 나타내고, \n\n  \n   을 만족시키는  의 값을 구하시오.","logical_id":"f8ca9555-019a-5be2-8ee2-0ddd08ab4e7e","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_problems (id,problem_set_id,display_order,statement,logical_id,version,state) values ('f8ca9555-019a-5be2-8ee2-0ddd08ab4e7e','95f3b3f7-f7e0-5cc9-9d98-4a42bc07724c',1,'[문제 1] 다음 물음에 답하시오. (50점)
