do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_scoring_criteria t where id='93f2770b-4bb6-590b-98f7-cbf90674952b'; if prior is not null then if not prior @> '{"id":"93f2770b-4bb6-590b-98f7-cbf90674952b","leaf_id":"c4d55464-cd19-58cc-8e91-d400610d1438","source_id":"5fc6b330-de11-590a-8b4e-7421ad7d09de","criterion_key":"q1-6","description":"급수 합이 3s_1인 t 결정","official_points":null,"rubric_dimensions":["logical_development","computation_accuracy","final_conclusion"]}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_scoring_criteria (id,leaf_id,source_id,criterion_key,description,official_points,rubric_dimensions) values ('93f2770b-4bb6-590b-98f7-cbf90674952b','c4d55464-cd19-58cc-8e91-d400610d1438','5fc6b330-de11-590a-8b4e-7421ad7d09de','q1-6','급수 합이 3s_1인 t 결정',NULL,ARRAY['logical_development','computation_accuracy','final_conclusion']::text[]); end if; end $row$;
do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solutions t where id='d7f824cf-eccf-529a-92e2-fc99a17123ae'; if prior is not null then if not prior @> '{"id":"d7f824cf-eccf-529a-92e2-fc99a17123ae","leaf_id":"c4d55464-cd19-58cc-8e91-d400610d1438","source_id":"9c858ca5-08b4-5a59-83cd-8fd85b029114","origin":"OFFICIAL","body":"평행이동한 함수가 홀함수인 조건으로 m=1,n=3이고 g(x)=x³−4x이다. f,g의 교점 x=−2,1 사이에서 적분하면 둘러싸인 넓이는 27/2이다.\n수선의 발을 H라 두고 합동·닮음을 이용하면 HR=BQ=(12−3x)/7이다. 삼각형 PQR 넓이는 (29x²−36x+72)/49이고 완전제곱으로 최소가 되는 x=18/29이다.\n닮음과 코사인법칙으로 다음 정삼각형의 한 변 비는 (1−2t)/√(1−t+t²)이다. 넓이의 공비 r=(1−2t)²/(1−t+t²), 등비급수 합 s_1/(1−r)=3s_1에서 0<t<1/2인 해 t=(5−√15)/10을 얻는다.","logical_id":"d7f824cf-eccf-529a-92e2-fc99a17123ae","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solutions (id,leaf_id,source_id,origin,body,logical_id,version,state) values ('d7f824cf-eccf-529a-92e2-fc99a17123ae','c4d55464-cd19-58cc-8e91-d400610d1438','9c858ca5-08b4-5a59-83cd-8fd85b029114','OFFICIAL','평행이동한 함수가 홀함수인 조건으로 m=1,n=3이고 g(x)=x³−4x이다. f,g의 교점 x=−2,1 사이에서 적분하면 둘러싸인 넓이는 27/2이다.
수선의 발을 H라 두고 합동·닮음을 이용하면 HR=BQ=(12−3x)/7이다. 삼각형 PQR 넓이는 (29x²−36x+72)/49이고 완전제곱으로 최소가 되는 x=18/29이다.
닮음과 코사인법칙으로 다음 정삼각형의 한 변 비는 (1−2t)/√(1−t+t²)이다. 넓이의 공비 r=(1−2t)²/(1−t+t²), 등비급수 합 s_1/(1−r)=3s_1에서 0<t<1/2인 해 t=(5−√15)/10을 얻는다.','d7f824cf-eccf-529a-92e2-fc99a17123ae',1,'DRAFT'); end if; end $row$;
