do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_problems t where id='75e0a7e1-2183-5982-968d-dc070e98cdab'; if prior is not null then if not prior @> '{"id":"75e0a7e1-2183-5982-968d-dc070e98cdab","problem_set_id":"f656858d-b3f6-5ef1-9eab-e5b6255e189a","display_order":2,"statement":"[문제 2] 다음 제시문을 읽고 물음에 답하시오. (50점)\n<가> 실수 전체의 집합에서 두 번 미분가능하고 이계도함수가 연속인 함수 가 모든 실수 에 대하여\n\n  \n  sin   cos    \n\n″       \n\n\n\n″  \n를 만족시킨다.\n<나> 함수 가 다음 조건을 만족시킨다.\n(ㄱ) 함수 는 사차함수이다.\n(ㄴ) 모든 실수 에 대하여\n  \n   \n\n\n″      \n  \n\n  \n\n이다.\n(ㄷ) 함수 가 닫힌구간    에서 증가한다.\n(ㄹ) 닫힌구간    에서 함수  를   로 정의하자.\n함수  의 역함수를  라 할 때,  축,  축, 직선    과\n곡선     ≤  ≤ 로 둘러싸인 도형의 넓이는 \n 이다.\n\n1. 의 값을 구하시오.\n2. 제시문 <나>의 조건 중 (ㄱ), (ㄴ)만을 이용하여  \n\n  의 값을 구하시오.\n3. 의 값을 구하시오.","logical_id":"75e0a7e1-2183-5982-968d-dc070e98cdab","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_problems (id,problem_set_id,display_order,statement,logical_id,version,state) values ('75e0a7e1-2183-5982-968d-dc070e98cdab','f656858d-b3f6-5ef1-9eab-e5b6255e189a',2,'[문제 2] 다음 제시문을 읽고 물음에 답하시오. (50점)
