do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solutions t where id='01310c47-91bc-59c4-a7bb-48e2415fb065'; if prior is not null then if not prior @> '{"id":"01310c47-91bc-59c4-a7bb-48e2415fb065","leaf_id":"0a1ffdc6-51c3-5df3-9dcc-645088443e89","source_id":"cb0735a3-2616-54c4-8fa2-e3382fa4acf9","origin":"OFFICIAL","body":"삼수선 정리와 정삼각형의 무게중심 성질로 DO=2√3,OP=2,AM=√(a²−9),AO=√(a²−12)를 얻는다. 네 삼각형 넓이의 곱은 12(a²−12)√(a²−9)이다.\n정사영 넓이비로 cosθ_1=√3/√(a²−9),cosθ_2=√(3(a²−12))/(2√(a²−9)),cosθ_3=√(a²−12)/(2√(a²−9))이다. 최대 코사인을 a<4와 a≥4로 나눠 주어진 각 조건을 풀면 a=3√6/2 또는 a=6이다.\n정육면체의 변을 x라 두고 단면 정삼각형과 삼수선 정리를 적용하면 (1+√3/2)x=3√3(1−x/2)이다. x=(18−3√3)/11이고 정사영 넓이는 x²cosθ_3=(351√7−108√21)/847이다.","logical_id":"01310c47-91bc-59c4-a7bb-48e2415fb065","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solutions (id,leaf_id,source_id,origin,body,logical_id,version,state) values ('01310c47-91bc-59c4-a7bb-48e2415fb065','0a1ffdc6-51c3-5df3-9dcc-645088443e89','cb0735a3-2616-54c4-8fa2-e3382fa4acf9','OFFICIAL','삼수선 정리와 정삼각형의 무게중심 성질로 DO=2√3,OP=2,AM=√(a²−9),AO=√(a²−12)를 얻는다. 네 삼각형 넓이의 곱은 12(a²−12)√(a²−9)이다.
정사영 넓이비로 cosθ_1=√3/√(a²−9),cosθ_2=√(3(a²−12))/(2√(a²−9)),cosθ_3=√(a²−12)/(2√(a²−9))이다. 최대 코사인을 a<4와 a≥4로 나눠 주어진 각 조건을 풀면 a=3√6/2 또는 a=6이다.
정육면체의 변을 x라 두고 단면 정삼각형과 삼수선 정리를 적용하면 (1+√3/2)x=3√3(1−x/2)이다. x=(18−3√3)/11이고 정사영 넓이는 x²cosθ_3=(351√7−108√21)/847이다.','01310c47-91bc-59c4-a7bb-48e2415fb065',1,'DRAFT'); end if; end $row$;
