do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solutions t where id='9b0125f9-81ce-5002-8564-0431c7959861'; if prior is not null then if not prior @> '{"id":"9b0125f9-81ce-5002-8564-0431c7959861","leaf_id":"1354113d-306d-5910-88d0-10ed0cbf2cdb","source_id":"85ccce86-7946-5dfe-b5c6-82151828c651","origin":"OFFICIAL","body":"f(x)=((1+x)^n+(1−x)^n)/(1+x^n)를 미분하면 0<x<1에서 양수임을 비교 부등식으로 확인한다. [0,1]에서 최솟값은 f(0)=2, 최댓값은 f(1)=2^(n−1)이다.\nn=8의 부등식 (a+b)^8+(a−b)^8≥2(a^8+b^8)를 두 번 적용한다. g,h의 조건을 대입하면 요구 식의 최댓값은 256/k^8이다. 등호는 s=1/k,f(s)=−1/k에서 성립하며 s=0,1은 조건을 만족하지 않는다.\nk를 8n²−2,4n²−2,7n²/2−2와 비교하여 역함수 관련 불연속점 수를 분류한다. 조건을 만족하는 값은 a_n=4n²−2이고 Σ[n=1,10]a_n=1520이다.","logical_id":"9b0125f9-81ce-5002-8564-0431c7959861","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solutions (id,leaf_id,source_id,origin,body,logical_id,version,state) values ('9b0125f9-81ce-5002-8564-0431c7959861','1354113d-306d-5910-88d0-10ed0cbf2cdb','85ccce86-7946-5dfe-b5c6-82151828c651','OFFICIAL','f(x)=((1+x)^n+(1−x)^n)/(1+x^n)를 미분하면 0<x<1에서 양수임을 비교 부등식으로 확인한다. [0,1]에서 최솟값은 f(0)=2, 최댓값은 f(1)=2^(n−1)이다.
n=8의 부등식 (a+b)^8+(a−b)^8≥2(a^8+b^8)를 두 번 적용한다. g,h의 조건을 대입하면 요구 식의 최댓값은 256/k^8이다. 등호는 s=1/k,f(s)=−1/k에서 성립하며 s=0,1은 조건을 만족하지 않는다.
k를 8n²−2,4n²−2,7n²/2−2와 비교하여 역함수 관련 불연속점 수를 분류한다. 조건을 만족하는 값은 a_n=4n²−2이고 Σ[n=1,10]a_n=1520이다.','9b0125f9-81ce-5002-8564-0431c7959861',1,'DRAFT'); end if; end $row$;
