do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_scoring_criteria t where id='39fa8e50-6d22-52ab-bac6-4305569079c3'; if prior is not null then if not prior @> '{"id":"39fa8e50-6d22-52ab-bac6-4305569079c3","leaf_id":"de9204d7-1565-57a0-8af2-ad0847467f3e","source_id":"6a322c9d-11fe-508a-a5c9-02e6d1f65b0e","criterion_key":"q1-7","description":"공식 세부 평가표(100점 척도, 문항 배점 50점) · 거리 |AP|의 최댓값(10)","official_points":null,"rubric_dimensions":["logical_development","computation_accuracy","final_conclusion"]}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_scoring_criteria (id,leaf_id,source_id,criterion_key,description,official_points,rubric_dimensions) values ('39fa8e50-6d22-52ab-bac6-4305569079c3','de9204d7-1565-57a0-8af2-ad0847467f3e','6a322c9d-11fe-508a-a5c9-02e6d1f65b0e','q1-7','공식 세부 평가표(100점 척도, 문항 배점 50점) · 거리 |AP|의 최댓값(10)',NULL,ARRAY['logical_development','computation_accuracy','final_conclusion']::text[]); end if; end $row$;
do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solutions t where id='b52ebab2-4ec8-5ddf-afc4-aaf5ab38693f'; if prior is not null then if not prior @> '{"id":"b52ebab2-4ec8-5ddf-afc4-aaf5ab38693f","leaf_id":"de9204d7-1565-57a0-8af2-ad0847467f3e","source_id":"508fd469-5091-5959-b7ba-b6831fc94507","origin":"OFFICIAL","body":"홀수와 짝수는 각각 2n+1개다. 조합의 대칭성에 따라 홀수 n개 이하와 짝수 n+1개 이상의 선택은 각각 2^(2n)가지이므로 곱은 2^(4n)이다.\n가법성에서 f(0)=0, f(1)=2, f(2)=4, f(2−x)=4−f(x). t=f(x)로 치환하면 k=∫₀⁴ t⁹(4−t)¹⁰dt이다. 부분적분을 반복하면 k=(9!10!/20!)4²⁰이므로 C(20,10)k=2³⁹/5이다.\n밑변 위 수선으로 높이 4, 좌우 수평 거리 3과 2를 얻어 A=(0,0), B=(6,0), C=(4,4), D=(3,4)로 놓는다. 내적 조건은 (2x−4)(3x−15)+(2y−4)(3y−4)=67/8. 정리하면 (x−7/2)²+(y−5/3)²=541/144이므로 원점에서 중심까지 거리 √541/6에 반지름 √541/12를 더한 √541/4가 최댓값이다.","logical_id":"b52ebab2-4ec8-5ddf-afc4-aaf5ab38693f","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solutions (id,leaf_id,source_id,origin,body,logical_id,version,state) values ('b52ebab2-4ec8-5ddf-afc4-aaf5ab38693f','de9204d7-1565-57a0-8af2-ad0847467f3e','508fd469-5091-5959-b7ba-b6831fc94507','OFFICIAL','홀수와 짝수는 각각 2n+1개다. 조합의 대칭성에 따라 홀수 n개 이하와 짝수 n+1개 이상의 선택은 각각 2^(2n)가지이므로 곱은 2^(4n)이다.
가법성에서 f(0)=0, f(1)=2, f(2)=4, f(2−x)=4−f(x). t=f(x)로 치환하면 k=∫₀⁴ t⁹(4−t)¹⁰dt이다. 부분적분을 반복하면 k=(9!10!/20!)4²⁰이므로 C(20,10)k=2³⁹/5이다.
밑변 위 수선으로 높이 4, 좌우 수평 거리 3과 2를 얻어 A=(0,0), B=(6,0), C=(4,4), D=(3,4)로 놓는다. 내적 조건은 (2x−4)(3x−15)+(2y−4)(3y−4)=67/8. 정리하면 (x−7/2)²+(y−5/3)²=541/144이므로 원점에서 중심까지 거리 √541/6에 반지름 √541/12를 더한 √541/4가 최댓값이다.','b52ebab2-4ec8-5ddf-afc4-aaf5ab38693f',1,'DRAFT'); end if; end $row$;
do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solution_steps t where id='8812145f-a001-5451-b47d-36e4b9343c85'; if prior is not null then if not prior @> '{"id":"8812145f-a001-5451-b47d-36e4b9343c85","solution_id":"b52ebab2-4ec8-5ddf-afc4-aaf5ab38693f","position":1,"body":"홀수와 짝수는 각각 2n+1개다. 조합의 대칭성에 따라 홀수 n개 이하와 짝수 n+1개 이상의 선택은 각각 2^(2n)가지이므로 곱은 2^(4n)이다.","criterion_id":null}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solution_steps (id,solution_id,position,body,criterion_id) values ('8812145f-a001-5451-b47d-36e4b9343c85','b52ebab2-4ec8-5ddf-afc4-aaf5ab38693f',1,'홀수와 짝수는 각각 2n+1개다. 조합의 대칭성에 따라 홀수 n개 이하와 짝수 n+1개 이상의 선택은 각각 2^(2n)가지이므로 곱은 2^(4n)이다.',NULL); end if; end $row$;
do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solution_steps t where id='e351c6ed-801f-5e44-8ec4-eae208f91cef'; if prior is not null then if not prior @> '{"id":"e351c6ed-801f-5e44-8ec4-eae208f91cef","solution_id":"b52ebab2-4ec8-5ddf-afc4-aaf5ab38693f","position":2,"body":"가법성에서 f(0)=0, f(1)=2, f(2)=4, f(2−x)=4−f(x). t=f(x)로 치환하면 k=∫₀⁴ t⁹(4−t)¹⁰dt이다. 부분적분을 반복하면 k=(9!10!/20!)4²⁰이므로 C(20,10)k=2³⁹/5이다.","criterion_id":null}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solution_steps (id,solution_id,position,body,criterion_id) values ('e351c6ed-801f-5e44-8ec4-eae208f91cef','b52ebab2-4ec8-5ddf-afc4-aaf5ab38693f',2,'가법성에서 f(0)=0, f(1)=2, f(2)=4, f(2−x)=4−f(x). t=f(x)로 치환하면 k=∫₀⁴ t⁹(4−t)¹⁰dt이다. 부분적분을 반복하면 k=(9!10!/20!)4²⁰이므로 C(20,10)k=2³⁹/5이다.',NULL); end if; end $row$;
