do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_problems t where id='733d61e4-1e76-5825-ab1b-af20da82a766'; if prior is not null then if not prior @> '{"id":"733d61e4-1e76-5825-ab1b-af20da82a766","problem_set_id":"e4a0cf38-466c-5038-8757-b061d5b31789","display_order":1,"statement":"5×5×1 격자에서 색칠된 정육면체의 꼭짓점을 피하는 최단경로의 수. A에서 4,6,8을 3:2:1, B에서 0,1을 6:4로 뽑아 (x+7)(x²−abx+a/2−6)의 세 근 중 최소거리를 X라 할 때 E(X). f(x)=1/sin²(2x), g(x)=∫[π/6,x] f(t)dt, h(x)=∫[π/6,x] g(t)dt일 때 x→0+에서 (h+g²)/f의 극한.","logical_id":"733d61e4-1e76-5825-ab1b-af20da82a766","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_problems (id,problem_set_id,display_order,statement,logical_id,version,state) values ('733d61e4-1e76-5825-ab1b-af20da82a766','e4a0cf38-466c-5038-8757-b061d5b31789',1,'5×5×1 격자에서 색칠된 정육면체의 꼭짓점을 피하는 최단경로의 수. A에서 4,6,8을 3:2:1, B에서 0,1을 6:4로 뽑아 (x+7)(x²−abx+a/2−6)의 세 근 중 최소거리를 X라 할 때 E(X). f(x)=1/sin²(2x), g(x)=∫[π/6,x] f(t)dt, h(x)=∫[π/6,x] g(t)dt일 때 x→0+에서 (h+g²)/f의 극한.','733d61e4-1e76-5825-ab1b-af20da82a766',1,'DRAFT'); end if; end $row$;
