do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_problems t where id='896fab08-ff65-5328-8e37-7bfc4ae6f8e3'; if prior is not null then if not prior @> '{"id":"896fab08-ff65-5328-8e37-7bfc4ae6f8e3","problem_set_id":"b0c31048-dcb8-5a9a-9e77-b788ed530b95","display_order":2,"statement":"지름 AB=2인 반원에서 PQ=1, QB<PB이고 지름 PQ인 반원이 AB와 접한다. θ=∠BOQ의 코사인·사인과 현 PQ의 점 T에서 AB에 수직으로 호에 이르는 거리 ST의 최댓값을 구한다. 반지름 1인 반구의 단면 원 C의 반지름이 1/2이고 C를 밑면으로 한 반구가 평면 α에 접할 때 C의 정사영 넓이를 구한다.","logical_id":"896fab08-ff65-5328-8e37-7bfc4ae6f8e3","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_problems (id,problem_set_id,display_order,statement,logical_id,version,state) values ('896fab08-ff65-5328-8e37-7bfc4ae6f8e3','b0c31048-dcb8-5a9a-9e77-b788ed530b95',2,'지름 AB=2인 반원에서 PQ=1, QB<PB이고 지름 PQ인 반원이 AB와 접한다. θ=∠BOQ의 코사인·사인과 현 PQ의 점 T에서 AB에 수직으로 호에 이르는 거리 ST의 최댓값을 구한다. 반지름 1인 반구의 단면 원 C의 반지름이 1/2이고 C를 밑면으로 한 반구가 평면 α에 접할 때 C의 정사영 넓이를 구한다.','896fab08-ff65-5328-8e37-7bfc4ae6f8e3',1,'DRAFT'); end if; end $row$;
