do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_scoring_criteria t where id='e3b8f5c5-2980-5ede-a596-0f31a741caa3'; if prior is not null then if not prior @> '{"id":"e3b8f5c5-2980-5ede-a596-0f31a741caa3","leaf_id":"6f5e02c4-bae8-5194-929f-4526b834f77d","source_id":"11b590d2-d6ff-5a0b-b390-3d0a74f6bf77","criterion_key":"q2-6","description":"공식 세부 평가표(100점 척도, 문항 배점 50점) · 원 C의 정사영 넓이(10)","official_points":null,"rubric_dimensions":["logical_development","computation_accuracy","final_conclusion"]}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_scoring_criteria (id,leaf_id,source_id,criterion_key,description,official_points,rubric_dimensions) values ('e3b8f5c5-2980-5ede-a596-0f31a741caa3','6f5e02c4-bae8-5194-929f-4526b834f77d','11b590d2-d6ff-5a0b-b390-3d0a74f6bf77','q2-6','공식 세부 평가표(100점 척도, 문항 배점 50점) · 원 C의 정사영 넓이(10)',NULL,ARRAY['logical_development','computation_accuracy','final_conclusion']::text[]); end if; end $row$;
do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solutions t where id='3224b617-b622-58cb-9cae-63222aaf7216'; if prior is not null then if not prior @> '{"id":"3224b617-b622-58cb-9cae-63222aaf7216","leaf_id":"6f5e02c4-bae8-5194-929f-4526b834f77d","source_id":"cb5af7bb-0e49-57e7-9bdf-66d08af399df","origin":"OFFICIAL","body":"PQ가 이루는 중심각은 π/3이다. 중점의 높이 RH=1/2이므로 sin(θ+π/3)+sinθ=1, 즉 3sinθ+√3cosθ=2이다. sin²θ+cos²θ=1과 제1사분면 조건으로 cosθ=(3√2+√3)/6, sinθ=(3−√6)/6이다.\n중점 R=(√2/2,1/2)이고 현의 직선은 y=−√2x+3/2이다. 호 위 점의 각을 θ+t라 하면 ST=(3cos t+√3 sin t−3)/2이다. 0≤t≤π/3에서 미분하면 t=π/6에서 증가에서 감소로 바뀌므로 최댓값은 √3−3/2이다.\n교선에 수직이고 O를 지나는 단면에서 RH=1/2, OR=√3/2이므로 두 평면 사이 각의 코사인은 RH/OR=1/√3이다. 원 C의 넓이 π/4에 곱하여 정사영 넓이 π/(4√3)을 구한다.","logical_id":"3224b617-b622-58cb-9cae-63222aaf7216","version":1,"state":"DRAFT"}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solutions (id,leaf_id,source_id,origin,body,logical_id,version,state) values ('3224b617-b622-58cb-9cae-63222aaf7216','6f5e02c4-bae8-5194-929f-4526b834f77d','cb5af7bb-0e49-57e7-9bdf-66d08af399df','OFFICIAL','PQ가 이루는 중심각은 π/3이다. 중점의 높이 RH=1/2이므로 sin(θ+π/3)+sinθ=1, 즉 3sinθ+√3cosθ=2이다. sin²θ+cos²θ=1과 제1사분면 조건으로 cosθ=(3√2+√3)/6, sinθ=(3−√6)/6이다.
중점 R=(√2/2,1/2)이고 현의 직선은 y=−√2x+3/2이다. 호 위 점의 각을 θ+t라 하면 ST=(3cos t+√3 sin t−3)/2이다. 0≤t≤π/3에서 미분하면 t=π/6에서 증가에서 감소로 바뀌므로 최댓값은 √3−3/2이다.
교선에 수직이고 O를 지나는 단면에서 RH=1/2, OR=√3/2이므로 두 평면 사이 각의 코사인은 RH/OR=1/√3이다. 원 C의 넓이 π/4에 곱하여 정사영 넓이 π/(4√3)을 구한다.','3224b617-b622-58cb-9cae-63222aaf7216',1,'DRAFT'); end if; end $row$;
