do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solution_steps t where id='cd61f6cf-992e-5bd1-8dca-3bb6bea7e2d3'; if prior is not null then if not prior @> '{"id":"cd61f6cf-992e-5bd1-8dca-3bb6bea7e2d3","solution_id":"3224b617-b622-58cb-9cae-63222aaf7216","position":2,"body":"중점 R=(√2/2,1/2)이고 현의 직선은 y=−√2x+3/2이다. 호 위 점의 각을 θ+t라 하면 ST=(3cos t+√3 sin t−3)/2이다. 0≤t≤π/3에서 미분하면 t=π/6에서 증가에서 감소로 바뀌므로 최댓값은 √3−3/2이다.","criterion_id":null}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solution_steps (id,solution_id,position,body,criterion_id) values ('cd61f6cf-992e-5bd1-8dca-3bb6bea7e2d3','3224b617-b622-58cb-9cae-63222aaf7216',2,'중점 R=(√2/2,1/2)이고 현의 직선은 y=−√2x+3/2이다. 호 위 점의 각을 θ+t라 하면 ST=(3cos t+√3 sin t−3)/2이다. 0≤t≤π/3에서 미분하면 t=π/6에서 증가에서 감소로 바뀌므로 최댓값은 √3−3/2이다.',NULL); end if; end $row$;
do $row$ declare prior jsonb; begin select to_jsonb(t) into prior from public.math_canonical_solution_steps t where id='b9375571-5252-5645-91a2-c3f3b20858fd'; if prior is not null then if not prior @> '{"id":"b9375571-5252-5645-91a2-c3f3b20858fd","solution_id":"3224b617-b622-58cb-9cae-63222aaf7216","position":3,"body":"교선에 수직이고 O를 지나는 단면에서 RH=1/2, OR=√3/2이므로 두 평면 사이 각의 코사인은 RH/OR=1/√3이다. 원 C의 넓이 π/4에 곱하여 정사영 넓이 π/(4√3)을 구한다.","criterion_id":null}'::jsonb then raise exception 'TASK20_CONTENT_DRIFT'; end if; else insert into public.math_canonical_solution_steps (id,solution_id,position,body,criterion_id) values ('b9375571-5252-5645-91a2-c3f3b20858fd','3224b617-b622-58cb-9cae-63222aaf7216',3,'교선에 수직이고 O를 지나는 단면에서 RH=1/2, OR=√3/2이므로 두 평면 사이 각의 코사인은 RH/OR=1/√3이다. 원 C의 넓이 π/4에 곱하여 정사영 넓이 π/(4√3)을 구한다.',NULL); end if; end $row$;

